CREATE OR REPLACE FUNCTION public.admin_save_account_v300(p_admin_session_token text, p_account_type text, p_account_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_password text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_permissions jsonb DEFAULT NULL::jsonb, p_branch_id text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT NULL::numeric, p_email text DEFAULT NULL::text, p_code text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_secondary_phone text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin jsonb;
v_type text := lower(trim(coalesce(p_account_type,'')));
v_id text := nullif(trim(coalesce(p_account_id,'')),'');
v_phone text := lower(trim(coalesce(p_phone,'')));
v_role text;
begin
select public.admin_session_identity_v147(p_admin_session_token)
into v_admin;

if not coalesce((v_admin->>'ok')::boolean,false)
or lower(trim(coalesce(v_admin->'admin'->>'role','')))
not in ('admin','أدمن','ادمن') then
return jsonb_build_object(
'ok',false,
'error','ADMIN_SESSION_INVALID'
);
end if;

if v_phone = '' then
return jsonb_build_object(
'ok',false,
'error','ACCOUNT_FIELDS_REQUIRED'
);
end if;

if v_type in ('employee','admin') then

v_role := case
when v_type='admin' then 'admin'
else coalesce(nullif(lower(trim(p_role)),''),'employee')
end;

if exists (
select 1
from public.employees e
where lower(trim(coalesce(e.phone,''))) = v_phone
and lower(trim(coalesce(e.role,''))) = v_role
and (v_id is null or e.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='courier' then

if exists (
select 1
from public.couriers c
where lower(trim(coalesce(c.phone,''))) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='branch' then

if exists (
select 1
from public.branches b
where lower(trim(coalesce(b.phone,''))) = v_phone
and (v_id is null or b.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='customer' then

if exists (
select 1
from public.customers c
where lower(trim(coalesce(c.phone,''))) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

else
return jsonb_build_object(
'ok',false,
'error','ACCOUNT_TYPE_INVALID'
);
end if;

return public.admin_save_account_v297(
p_admin_session_token,
p_account_type,
p_account_id,
p_name,
p_phone,
p_password,
p_role,
p_permissions,
p_branch_id,
p_delivery_fee,
p_email,
p_code,
p_country,
p_state,
p_address,
p_secondary_phone
);
end;
$function$

CREATE OR REPLACE FUNCTION public.branch_save_courier_v304(p_branch_session_token text, p_courier_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_password text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT NULL::numeric)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_branch_id text;
v_id text := nullif(trim(coalesce(p_courier_id,'')),'');
v_name text := trim(coalesce(p_name,''));
v_phone text := trim(coalesce(p_phone,''));
v_password text := coalesce(p_password,'');
v_hash text;
v_saved_id text;
begin
v_branch_id := private.require_branch_session_v148(p_branch_session_token);

if v_name = '' or v_phone = '' then
return jsonb_build_object('ok',false,'error','ACCOUNT_FIELDS_REQUIRED');
end if;

if v_id is null and v_password = '' then
return jsonb_build_object('ok',false,'error','PASSWORD_REQUIRED');
end if;

if v_password <> '' and length(v_password) < 8 then
return jsonb_build_object('ok',false,'error','PASSWORD_TOO_SHORT');
end if;

if exists (
select 1
from public.couriers c
where trim(coalesce(c.phone,'')) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

if v_password <> '' then
v_hash := crypt(v_password, gen_salt('bf'));
end if;

if v_id is null then
insert into public.couriers(
branch_id,
name,
phone,
password,
delivery_fee,
is_active
)
values(
v_branch_id,
v_name,
v_phone,
v_hash,
p_delivery_fee,
true
)
returning id::text into v_saved_id;

else
update public.couriers
set
name = v_name,
phone = v_phone,
delivery_fee = p_delivery_fee,
password = case
when v_hash is null then password
else v_hash
end
where id::text = v_id
and branch_id::text = v_branch_id
returning id::text into v_saved_id;
end if;

if v_saved_id is null then
return jsonb_build_object(
'ok',false,
'error','COURIER_NOT_FOUND_OR_NOT_OWNED'
);
end if;

return jsonb_build_object(
'ok',true,
'id',v_saved_id
);

exception
when unique_violation then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_courier_action_v308(p_admin_session_token text, p_courier_id text, p_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin_id text;
v_action text := lower(trim(coalesce(p_action,'')));
v_linked boolean;
begin
v_admin_id := private.require_admin_session_v147(p_admin_session_token);

if coalesce(v_admin_id,'') = '' then
return jsonb_build_object('ok',false,'error','INVALID_ADMIN_SESSION');
end if;

if v_action = 'toggle' then
update public.couriers
set is_active = not coalesce(is_active,true)
where id::text = p_courier_id;

if not found then
return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND');
end if;

return jsonb_build_object('ok',true,'result','TOGGLED');

elsif v_action = 'delete' then
select exists(
select 1 from public.orders
where courier_id::text = p_courier_id
limit 1
) into v_linked;

if v_linked then
update public.couriers
set is_active = false
where id::text = p_courier_id;
else
delete from public.couriers
where id::text = p_courier_id;
end if;

if not found then
return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND');
end if;

return jsonb_build_object(
'ok',true,
'result',
case when v_linked then 'DISABLED_LINKED' else 'DELETED' end
);
end if;

return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACTION');
end;
$function$

